'use strict';
/* TỰ SINH bởi tools/build-worker.js — đừng sửa tay. */
const AI_WORKER_SRC="'use strict';\n/* [CONFIG] Hằng số: luật, màu, ánh sáng, thông số animation. Chỉnh giao diện/cảm giác ở đây. */\nconst CFG={\n  N:9,                 /* bàn N x N ô */\n  PITCH:1.2,           /* bước giữa hai ô */\n  CELL:1.1,            /* cạnh ô (khe giữa hai ô = PITCH - CELL) */\n  CELL_H:.2,           /* độ dày ô; mặt ô nằm ở CELL_H/2 */\n  WALLS:10,            /* số tường mỗi bên */\n  MAX_PLY:300,         /* máy đấu máy: quá số nước này thì hòa */\n  PVE_DELAY:600,       /* đấu với máy: máy \"suy nghĩ\" bao lâu (ms) trước khi đi */\n\n  /* Hai bên chơi. glow=true: mặt vẽ bằng emissiveMap (cần cho thân đen, vì đen nhân gì cũng vẫn đen) */\n  PLAYERS:[\n    {name:'Trắng',sym:'○',body:0xe9e5db,faceBg:'#ffffff',faceFg:'#16161b',glow:false},\n    {name:'Đen',  sym:'●',body:0x1b1b21,faceBg:'#000000',faceFg:'#ffffff',glow:true}\n  ],\n\n  BOARD:{\n    frame:0x2e1c10,                         /* viền gỗ tối */\n    edge:[0xece8de,0x14141a],               /* dải ngà (đích của Trắng) / dải đen (đích của Đen) */\n    woodLight:[['#dcb67f',11],['#d3ab72',23]],   /* [màu, hạt giống vân gỗ] */\n    woodDark:[['#8d5b33',37],['#7f4f2b',51]],\n    goalWood:[                              /* ô đích: [0] đích của Trắng (hàng đầu) sáng hẳn, [1] đích của Đen (hàng cuối) tối hẳn */\n      [['#f4e4bf',61],['#ebd6a3',73]],\n      [['#3d2312',83],['#31200f',97]]\n    ],\n    hint:0x35c46a,                          /* ô đi được: lớp phủ xanh lá phẳng (không ăn đèn/bóng nên đều màu) */\n    hintOpacity:.45,                        /* độ đậm tối đa của lớp phủ */\n    arrowSize:.75,                          /* cỡ mũi tên phím trên ô gợi ý (so với cạnh ô) */\n    arrowOpacity:.8,                        /* độ đậm tối đa của mũi tên */\n    hintFade:9,                           /* tốc độ fade in/out (càng lớn càng nhanh) */\n    ghostOk:0x3db8ff,                       /* tường \"ma\" đặt được: xanh da trời phát sáng */\n    ghostBad:0xe8392f,                     /* tường \"ma\" đặt sai chỗ */\n    shadowOpacity:.35\n  },\n\n  LIGHT:{\n    hemi:[0xffffff,0x7a6a5a,.45],\n    sun:[0xfff0dc,.8],sunPos:[5,10,6],\n    fill:[0xdde6ff,.25],fillPos:[-6,5,-5],\n    shadowSize:2048\n  },\n\n  PAWN:{\n    R:.4,H:.5,scale:.55,pivot:.44,          /* kích thước thân Lathe, tỉ lệ quân, độ cao trục xoay (tâm thân) */\n    roughness:.8,                           /* quân nhám */\n    landJitter:.1,                          /* đáp lệch tâm ô tối đa */\n    yawJitter:.4,                           /* hướng mặt lúc đáp lệch tối đa (rad) */\n    sway:.2,                                /* nhún nghiêng sang hai bên khi đi (rad) */\n    plant:.7,                               /* 1 = chân bám đất khi nghiêng, 0 = cả người trượt theo */\n    bob:.035                                /* nhún lên xuống theo từng bước */\n  },\n\n  WALL:{\n    height:.5,restY:.255,ghostY:.35,\n    ghost:{speed:.8,glow:[.8,1.6],alpha:[.5,.78]},   /* tường \"ma\" thở: nhịp/giây, độ sáng phát ra [min,max], độ đậm [min,max] */\n    drop:[2.2,3],                           /* độ cao rơi ngẫu nhiên [min,max] */\n    gravity:20,\n    bounce:[.2,.35],                        /* hệ số nảy ngẫu nhiên [min,max] */\n    stopSpeed:1.1,                          /* nảy yếu hơn mức này thì dừng hẳn */\n    roughness:.35,metalness:.05\n  },\n\n  /* Thanh khả năng thắng (xem eval.js). Các số này được fit trên ~12.000 thế cờ từ ván máy đấu máy; chỉnh tay thì xem ghi chú từng dòng. */\n  EVAL:{\n    depth:3,      /* tìm kiếm mấy nước (ply). 3 ≈ 4ms/thế; 4 chậm gấp ~4 lần mà gần như không chính xác hơn */\n    nodes:4000,   /* trần số nút tìm kiếm cho mỗi lần chấm (chống đơ máy yếu); hết ngân sách thì dùng độ sâu trước đó */\n    top:6,        /* mỗi nút chỉ thử tối đa chừng này tường \"đáng đặt nhất\" (bên trong cây) */\n    topRoot:8,    /* như trên nhưng cho nút gốc */\n    tempo:.5,     /* lợi thế của bên có lượt, tính bằng bước đi (đúng cho cuộc đua thuần túy) */\n    wallA:2.1,    /* giá trị của tường dư: w tường đáng  wallA*w + wallB*w²  bước đi (wallB âm = càng nhiều càng giảm dần) */\n    wallB:-.16,\n    kZero:.33,    /* độ \"mờ\" của đường cong xác suất khi bên đang thua HẾT tường: nhỏ = dẫn 1-2 bước là gần chắc thắng (vẫn chừa chỗ cho hai quân cản nhau) */\n    k0:.55,       /* độ mờ khi bên thua còn tường: k = k0 + kWall * (số tường bên thua còn) */\n    kWall:.77,    /* mỗi tường bên thua còn giữ làm đường cong mờ thêm chừng này (còn tường = còn đường lật kèo) */\n    max:.99       /* chặn trên của xác suất khi ván chưa kết thúc: 99% / 1% */\n  },\n\n  /* Hai AI có \"tính cách\" (js/ai/attacker.js, defender.js). Mỗi ván mỗi AI bốc ngẫu nhiên một bộ tính cách trong các khoảng dưới đây\n     (dạng [min,max] = số ngẫu nhiên trong khoảng; dạng [[giá trị, trọng số],...] = chọn có trọng số). Khoảng càng hẹp thì càng ít đổi gió.\n     Đơn vị \"bước\" = số ô đường đi. net của một tường = (đối thủ phải đi thêm) - (mình phải đi thêm); đặt tường tốn một lượt nên net=1 là hòa vốn. */\n  AI:{\n    biet:{                                      /* Mr. Biết: boss tìm kiếm sâu + đọc đối thủ + chọn nước mềm cho khó đoán */\n      depth:8,nodes:30000,ms:500,msMain:160,    /* trần tìm kiếm: độ sâu tối đa, số nút, thời gian (ms) mỗi nước; msMain = trần khi buộc phải chạy ở luồng chính (không có Worker) */\n      topRoot:12,top:6,top2:4,                  /* số tường thử ở gốc / nút trong (còn >= 3 nước) / nút gần lá */\n      wallA:4,wallR:.85,tempo:.5,             /* tường dư thứ k đáng A*R^(k-1) bước đi (R<1: càng nhiều càng rẻ), lợi thế người có lượt */\n      jitter:.12,                               /* mỗi ván giá trị tường lệch ngẫu nhiên ± chừng này (tỉ lệ) */\n      rep:.8,                                   /* phạt mỗi lần lặp lại thế cờ cũ (bước đi) */\n      margin:.3,temp:.25,openBoost:2,openPly:8, /* chọn mềm giữa các nước kém nước tốt nhất < margin bước; mở màn margin x openBoost */\n      effPrior:1.6,effK:2,effLo:.6,effHi:1.4    /* đọc đối thủ: hiệu quả trung bình dự kiến mỗi tường, độ tin vào dự kiến, biên điều chỉnh */\n    },\n    mirror:{                                    /* Mr. Bắt Chước: chơi gương đối xứng, chỉ ra đòn thật khi thấy sơ hở */\n      loyal:[.85,1],                            /* xác suất mỗi lượt chịu bắt chước (còn lại: đi ngắn nhất) */\n      strike:[[2,.3],[3,.45],[4,.25]],          /* có tường lời >= số bước này (đã trừ phần mình chậm) thì bỏ gương mà đặt luôn */\n      panic:[[2,.4],[3,.6]],                    /* đối thủ cách đích <= số này thì thôi chơi gương, đặt tường cản */\n      tol:[0,1.5]                               /* tường đối xứng làm mình thiệt hơn đối thủ quá số bước này thì bỏ qua */\n    },\n    keeper:{                                    /* Mr. Thủ Môn: chạy nước rút, giữ tường, đóng cổng khi đối thủ áp sát vạch đích */\n      zone:[[6,.3],[7,.4],[8,.3]],              /* đối thủ cách đích <= số này bước thì bắt đầu đóng cổng */\n      homeW:[.5,1.5],                           /* thưởng cho tường ngang sát hàng nhà (<= 2 hàng) */\n      linkW:[.3,1.2],                           /* thưởng cho tường nối với tường khác / mép bàn (hàng rào liền) */\n      need:[[2,.7],[3,.3]],                     /* tường phải lời >= số bước này (đã trừ phần mình chậm) mới chịu đặt */\n      reserve:[[0,.7],[1,.3]],                  /* số tường giữ lại, chỉ xả khi đối thủ cách đích <= 2 bước */\n      lead:[[2,.3],[3,.7]],                     /* dẫn trước đối thủ chừng này bước thì khỏi đóng cổng, cứ chạy */\n      temp:[.15,.5]                             /* nhiệt độ chọn giữa 3 tường tốt nhất */\n    },\n    control:{                                   /* Mr. Kiểm Soát: dựng cụm tường giữa bàn trước, rồi ứng biến (mỗi ván bốc một tính cách) */\n      open:[[0,.4],[1,.4],[2,.2]],              /* số nước đi quân trước khi bắt đầu dựng thế trận */\n      claim:[[2,.3],[3,.45],[4,.25]],           /* số tường muốn dựng ở trung tâm */\n      radius:[2.5,3.5],                         /* \\\"trung tâm\\\" rộng tới đâu (khoảng cách Manhattan từ nút giữa bàn; tường sát tâm = 1) */\n      centerW:[.5,1.1],                         /* thưởng độ gần tâm khi dựng thế trận */\n      chainW:[.3,.9],                           /* thưởng cho tường chạm vào tường của chính mình (cụm liền khối) */\n      cap:[[0,.7],[1,.3]],                      /* tường dựng thế trận được làm mình chậm tối đa mấy bước */\n      safe:[[4,.5],[5,.5]],                     /* chỉ dựng thế trận khi đối thủ còn cách đích >= số bước này */\n      need:[[1,.4],[2,.5],[3,.1]],              /* ứng biến: tường phải lời >= số này (bị bỏ lại thì giảm 1) */\n      reserve:[[0,.5],[1,.5]],                  /* số tường giữ lại cho lúc đối thủ cận đích */\n      lead:[[2,.5],[3,.5]],                     /* dẫn trước chừng này bước thì khỏi đặt tường, cứ chạy */\n      temp:[.15,.5]                             /* nhiệt độ chọn giữa 3 tường tốt nhất */\n    },\n    gambler:{                                   /* Mr. Con Bạc: mỗi ván cược một kiểu — all-in ném tường sớm, hoặc keo kiệt rồi xả liều */\n      mode:[['allin',.5],['miser',.5]],         /* tỉ lệ hai kiểu cược */\n      open:[[0,.6],[1,.4]],                     /* (all-in) số nước đi quân trước khi bắt đầu ném tường */\n      cap:[[1,.5],[2,.5]],                      /* (all-in) chấp nhận tự chậm tối đa mấy bước cho mỗi tường */\n      need:[[1,.6],[2,.4]],                     /* (all-in) tường phải lời (net) >= số này mới ném */\n      lead:[[3,.5],[4,.5]],                     /* (all-in) dẫn trước chừng này bước thì thôi cược, chạy về */\n      trigger:[[2,.5],[3,.5]],                  /* (keo kiệt) đối thủ cách đích <= số này thì bắt đầu xả */\n      tilt:[[3,.5],[4,.5]],                     /* (keo kiệt) mình bị bỏ lại >= số bước này thì xả gỡ gạc */\n      yolo:[.04,.14],                           /* xác suất mỗi lượt \\\"thấy hên là đánh\\\" tường lời >= 2 bước */\n      temp:[.2,.7]                              /* nhiệt độ chọn giữa 3 tường tốt nhất */\n    },\n    thug:{                                      /* Mr. Lưu Manh: hợm hĩnh, sát mặt, hay chọc (mỗi ván bốc một tính cách trong các khoảng này) */\n      opening:[[0,.55],[1,.3],[2,.15]],         /* số nước đi quân khoe mẽ trước khi dựng tường */\n      swagger:[0,.15],                          /* xác suất mỗi lượt đi dạo một bước thay vì đặt tường */\n      lead:[[1,.4],[2,.4],[3,.2]],             /* dẫn trước đối thủ chừng này bước thì chạy về đích (99 = cứ chọc đến hết tường) */\n      near:[.05,.4],                            /* ưu tiên tường gần quân đối thủ (mỗi ô khoảng cách trừ bấy nhiêu điểm) */\n      headW:[0,1.2],                            /* thưởng cho tường chặn đúng 1-2 bước kế tiếp của đối thủ */\n      selfW:[1,1.8],                            /* mỗi bước mình bị chậm trừ bấy nhiêu điểm (càng cao càng giữ đường mình thoáng) */\n      cap:[[0,.3],[1,.4],[2,.3]],               /* bỏ tường nào làm đường mình dài thêm quá số bước này */\n      temp:[.15,.6]                             /* nhiệt độ chọn giữa 4 tường tốt nhất: cao = khó đoán hơn */\n    },\n    attacker:{                                  /* Mr. Lấn Ép: dồn tường để kéo dài đường đối thủ */\n      opening:[0,2],                            /* số nước đi quân đầu tiên trước khi bắt đầu đặt tường */\n      need:[[1,.2],[2,.55],[3,.25]],            /* \"giá trị\" tối thiểu của tường để chịu đặt (1 = đặt cả tường hòa vốn để quấy rối) */\n      selfCap:[[0,.65],[1,.35]],                /* tường được phép làm đường mình dài thêm tối đa bao nhiêu bước */\n      eager:[.8,1],                             /* xác suất chịu đặt khi có tường đạt chuẩn (còn lại: đi bộ, đánh lạc hướng) */\n      linkW:[0,1.2],                            /* thưởng cho tường nối liền với tường/mép bàn (xây hàng rào dài) */\n      lineW:[.6,1.6],                           /* thưởng thêm cho tường nối THẲNG HÀNG vào tường của chính mình (rào dài một mạch) */\n      temp:[.2,.7],                             /* nhiệt độ chọn giữa các tường tốt nhất: cao = khó đoán hơn */\n      selfW:1.4,                                /* mỗi bước mình bị chậm trừ bấy nhiêu điểm (>1 = giữ đường mình thoáng) */\n      gambit:.07                                /* xác suất mỗi lượt chọn tường hạng 2-3 thay vì hạng 1 */\n    },\n    defender:{                                  /* Mr. Nhây Nhưa: giữ tường, phản công, đi quân thông minh */\n      reserve:[[1,.3],[2,.45],[3,.25]],         /* số tường giữ lại cho tình huống cần thiết (không dùng chủ động) */\n      counterNeed:[[1,.6],[2,.4]],             /* khi bị đặt tường: giá trị tối thiểu của tường phản công */\n      danger:[[2,.3],[3,.5],[4,.2]],            /* đối thủ cách đích <= số này thì bắt đầu đặt tường kể cả khi chưa bị đặt tường */\n      linkW:[.3,1.3],                           /* thưởng cho tường nối với tường sẵn có (tận dụng tường của đối thủ) */\n      newLinkW:[1.5,2.6],                       /* thưởng thêm khi nối đúng vào tường đối thủ vừa đặt (phá bẫy) */\n      vulnW:[.7,1.3],                           /* trọng số \"né chỗ dễ bị chặn\" khi chọn nước đi */\n      temp:[.15,.5],\n      feint:.03                                 /* xác suất mỗi lượt bỏ qua phản công để đi bộ (khó đoán hơn) */\n    }\n  },\n\n  /* Pháo bông khi thắng. Tổng hạt = bursts * per (nên giữ dưới ~600 cho nhẹ). */\n  FX:{\n    bursts:7,per:64,                        /* số đợt nổ, số hạt mỗi đợt */\n    wait:.55,span:2.6,                      /* đợi quân đáp xong rồi mới nổ; các đợt nổ rải đều trong span giây */\n    speed:[1.7,3.4],life:[1.5,2.5],         /* tốc độ bung ra, thời gian sống của hạt (giây) */\n    size:[.16,.32],                         /* kích thước hạt (đơn vị thế giới) */\n    height:[.9,2.6],spread:1,               /* độ cao tâm nổ so với mặt bàn, độ lệch ngang quanh quân */\n    drag:2.2,gravity:4.8,                   /* cản gió (bung nhanh rồi chậm lại), trọng lực */\n    palette:[0xff4d6d,0xffd23f,0x3ddc97,0x4cc9f0,0xb388ff,0xff9f1c,0xffffff,0xff6ad5]\n  },\n\n  /* Ăn mừng khi chạm ô đích (xem Pawns.celStart/celStep). Mỗi lần bốc thăm đều nhau một trong 4 kiểu. */\n  CELEB:{\n    kinds:['flip','hiphop','bounce','run'],  /* mỗi kiểu 25% */\n    force:null,                              /* đặt 'flip' | 'hiphop' | 'bounce' | 'run' để luôn xem một kiểu (thử/chỉnh) */\n    dur:{flip:1.25,hiphop:3.2,bounce:3,run:3},   /* thời lượng từng kiểu (giây) */\n    flip:{air:1.1},                          /* lộn một vòng tại chỗ: độ cao bay */\n    hiphop:{turns:4,drop:.16,swing:9,legAmp:.8},   /* trồng cây chuối: số vòng xoay, hạ thân cho đầu chạm sàn, nhịp và biên độ chân (rad) */\n    bounce:{hops:5,h:.4,squash:.3},          /* nảy cà tưng: số lần nảy, độ cao, độ bẹp lúc chạm đất */\n    run:{radius:.3,laps:4,lean:.25,cadence:17}   /* chạy vòng quanh tâm ô: bán kính (< .33 để không ra khỏi ô), số vòng, độ nghiêng vào trong, nhịp chân */\n  },\n\n  /* Nhãn chất lượng nước đi (xem review.js, view/badges.js). Mọi ngưỡng là \"mất bao nhiêu điểm xác suất thắng so với nước tốt nhất\" (0.05 = 5%). */\n  REVIEW:{\n    walls:8,        /* mỗi lần chấm: thử mọi nước đi quân + chừng này tường đáng đặt nhất (+ chính nước đã đi) để tìm \"nước tốt nhất\" */\n    bookPly:4,      /* những nước đầu ván (mỗi bên 2 nước) mà đi quân gần tối ưu thì gọi là \"sách giáo khoa\" */\n    t:{\n      book:.03,     /* nước khai cuộc: mất tối đa bấy nhiêu vẫn là sách giáo khoa */\n      top:.01,      /* điều kiện \"gần như nước tốt nhất\" để xét Thiên tài / Chính xác duy nhất */\n      gap:.12,      /* nước tốt nhất phải hơn nước thứ hai ít nhất bấy nhiêu (tức gần như là nước duy nhất) */\n      swing:.12,    /* Thiên tài: nước đó còn phải đẩy xác suất thắng của mình lên ít nhất bấy nhiêu so với trước khi đi */\n      best:.005,excellent:.02,good:.05,ok:.09,   /* các mức mất điểm: Tốt nhất / Xuất sắc / Tốt / Ổn */\n      /* Thế đã phân thắng bại (theo chess.com / Lichess / Duolingo: khi đã thắng hoặc thua hẳn, mất thêm điểm không còn ý nghĩa): */\n      lost:.08,won:.92,           /* xác suất ngoài khoảng [lost, won] coi như \"đã định\": mọi giá trị trong vùng đó được xem là bằng nhau */\n      aliveFrom:.08,aliveTo:.35,  /* nước tốt nhất còn <= aliveFrom: đã thua, không trách ai; >= aliveTo: trách đủ; ở giữa tăng dần mượt */\n      lead:{best:.5,excellent:1.5,good:3,ok:6},   /* khi cả nước tốt nhất lẫn nước đã đi đều thắng chắc: số bước đi lãng phí tối đa cho Tốt nhất / Xuất sắc / Tốt / Ổn (quá mức đó: Thiếu chính xác) */\n      flat:.005,                  /* mọi nước ứng viên chênh nhau không quá mức này: không có lựa chọn nào đáng kể, không gán nhãn */\n      brilMin:.30,greatMin:.12,   /* sau nước đi mà vẫn dưới mức này thì không được gọi Thiên tài / Chính xác duy nhất (chess.com: không được ở thế xấu) */\n      inacc:.15,mistake:.30,                     /* từ .09: Thiếu chính xác; từ .15: Sai lầm; từ .30: Sai lầm nghiêm trọng */\n      missPrev:.12,missBest:.55                  /* Bỏ lỡ: đối thủ vừa sai lầm (mất >= missPrev) mà mình không tận dụng dù có nước giữ được >= missBest */\n    },\n    /* Hiển thị sprite: tồn tại life giây (máy đấu máy nhanh thì ngắn lại theo S.delay), fade in/out trong lượt đó */\n    debug:false,    /* true: in ra console bảng chi tiết cho mỗi nước đi (best, played, before, loss, nhãn...) để dò lỗi gán nhãn */\n    life:2.4,in:.25,out:.45,\n    pawnY:1.3,wallY:1.15,size:1,rise:.15,    /* độ cao trên đầu quân / trên tường, kích thước (đơn vị thế giới), độ trôi lên */\n    dly:{move:.15,wall:.5},                  /* chờ bao lâu mới hiện (tường cần thời gian rơi xuống) */\n    labels:{\n      brilliant:{name:'Thiên tài',color:'#1baca6',icon:'!!'},\n      great:{name:'Chính xác duy nhất',color:'#5c8bb0',icon:'!'},\n      best:{name:'Tốt nhất',color:'#96bc4b',icon:'star'},\n      excellent:{name:'Xuất sắc',color:'#7fb04a',icon:'thumb'},\n      good:{name:'Tốt',color:'#97af8b',icon:'check'},\n      ok:{name:'Ổn',color:'#9b9ba3',icon:'eq'},\n      book:{name:'Sách giáo khoa',color:'#a88865',icon:'book'},\n      inaccuracy:{name:'Thiếu chính xác',color:'#f7c631',icon:'?!'},\n      mistake:{name:'Sai lầm',color:'#e58f2a',icon:'?'},\n      miss:{name:'Bỏ lỡ',color:'#ee6b5c',icon:'x'},\n      blunder:{name:'Sai lầm nghiêm trọng',color:'#ca3431',icon:'??'},\n      hopeless:{name:'Hết cách',color:'#7d8fa3',icon:'sad'},        /* hết cửa thắng, mọi nước như nhau: mặt khóc (xám xanh, không dùng đỏ để khỏi giống nhãn lỗi) */\n      forced:{name:'Nước ép buộc',color:'#9b9ba3',icon:'arrow'}     /* chỉ có đúng một nước đi */\n    }\n  },\n\n  CAM:{pitch:.955,dist:14.1,minPitch:.35,maxPitch:1.45,minZoom:.6,maxZoom:1.6,\n       followDist:7,followPitch:.5,followLook:.35,\n       faceDist:5.5,facePitch:.3}   /* khi thắng: camera lia ra trước mặt quân thắng, gần hơn và thấp hơn */   /* chế độ bám theo quân: khoảng cách, góc nghiêng, độ cao điểm nhìn */\n};\n\n;\n'use strict';\n/* [UTIL] Hàm nhỏ dùng chung + hằng số hình học bàn cờ suy ra từ CFG. */\nconst TAU=Math.PI*2;\nconst $=id=>document.getElementById(id);\nconst rand=(a,b)=>a+Math.random()*(b-a);\nconst rsign=()=>Math.random()<.5?-1:1;\nconst clamp=(x,a,b)=>x<a?a:x>b?b:x;\nconst smooth=t=>t*t*(3-2*t);\nconst angDiff=(a,b)=>Math.atan2(Math.sin(a-b),Math.cos(a-b));   /* góc xoay ngắn nhất từ b tới a */\nconst pick1=a=>a[Math.floor(Math.random()*a.length)];\nconst nextFrame=()=>new Promise(r=>setTimeout(r,16));\n\nconst N=CFG.N,WN=N-1,HALF=WN/2,TOP=CFG.CELL_H/2;   /* WN = số khe tường mỗi chiều */\nconst cellX=c=>(c-HALF)*CFG.PITCH,cellZ=r=>(r-HALF)*CFG.PITCH;\nconst wallX=c=>(c+.5-HALF)*CFG.PITCH,wallZ=r=>(r+.5-HALF)*CFG.PITCH;\nconst wallIdx=x=>clamp(x,0,WN-1);\n\n;\n'use strict';\n/* [STATE] Trạng thái ván cờ (một object duy nhất: S) + vài hàm hỏi nhanh về \"ai đang chơi\". */\nconst S={\n  pl:null,          /* vị trí hai quân: [{r,c},{r,c}] */\n  ws:null,          /* tường đã đặt: {h:Uint8Array(WN*WN), v:...} */\n  left:null,        /* số tường còn lại của mỗi bên */\n  turn:0,mode:'move',orient:'h',\n  over:false,draw:false,ply:0,\n  hov:null,         /* ô tường đang rê chuột {r,c} */\n  ai:[null,null],   /* mỗi bên do ai điều khiển: null = người, chuỗi = id của AI trong AIs */\n  me:-1,            /* bên của người chơi (0 = Trắng, 1 = Đen); -1 nếu máy đấu máy */\n  view:0,           /* camera mặc định nhìn từ phía nào: phe của người chơi, hoặc ngẫu nhiên khi máy đấu máy */\n  paused:false,delay:400,\n  analysis:true,    /* đang hiện thanh khả năng thắng + nhãn nước đi? (phím T). Tắt thì không tính gì cả: khỏi tốn máy */\n  analysisLock:false/* true: chế độ này không cho bật/tắt (vd đấu online: giữ tắt để không ai nhờ engine hỗ trợ) */\n};\n\nconst isAI=p=>S.ai[p]!==null;                 /* bên p do máy điều khiển? */\nconst allAI=()=>isAI(0)&&isAI(1);             /* máy đấu máy */\nconst humanTurn=()=>!S.over&&!isAI(S.turn);   /* đến lượt người bấm chuột? */\n\n/* Phím E xoay vòng: quân mình → quân kia → mặc định. Máy đấu máy thì Trắng → Đen → mặc định. */\nconst viewOrder=()=>S.me<0?[0,1]:[S.me,1-S.me];\n/* Camera mặc định nhìn từ phía nào (chọn lúc bắt đầu ván, xem App.newGame) */\nconst homeSide=()=>S.view;\n\n;\n'use strict';\n/* [CORE] Lõi luật chơi — thuần logic, KHÔNG đụng biến toàn cục (S, N, WN, CFG), DOM hay 3D.\n   Client, AI (worker) và sau này cả server (Cloudflare Durable Object) đều dùng chung file này: luật chỉ có MỘT bản.\n\n   Cách dùng:\n     const R=Core.make(Core.ruleset('classic'));        // R = bộ luật gắn với một ruleset (cỡ bàn, số tường...)\n     const st=R.newState();                             // trạng thái ván mới\n     R.check(st,{move:[r,c]})  hoặc  {wall:{o:'h'|'v',r,c}}   → {ok:true} | {ok:false,reason}\n     R.apply(st,action)                                 // kiểm tra + áp dụng + chuyển lượt + xét thắng; trả {ok,over,winner,reason}\n     R.moves(st,p)  R.dist(st,p,{r,c})  R.canWall(st,o,r,c) ...   // các hàm hỏi luật\n\n   Trạng thái st (chỉ những trường lõi dùng; client cho phép có thêm trường khác, lõi bỏ qua):\n     pl:[{r,c},{r,c}]  vị trí quân (0 = Trắng đi trước, xuất phát hàng cuối; 1 = Đen, xuất phát hàng 0)\n     ws:{h:Uint8Array(WN*WN), v:Uint8Array(WN*WN)}  tường đã đặt (1 = có), chỉ số r*WN+c\n     left:[số tường còn lại của mỗi bên]   turn:0|1   ply:số nước đã đi   over:bool   winner:-1|0|1   draw:bool\n   Tường (o,r,c): 'h' nằm giữa hàng r và r+1, phủ cột c và c+1; 'v' nằm giữa cột c và c+1, phủ hàng r và r+1.\n\n   Ruleset: {id,name,N,walls,maxPly}. Thêm chế độ mới = thêm một ruleset (sau này kèm hook đầu lượt/sau hành động). */\nconst Core=(function(){\n  const D=[[-1,0],[1,0],[0,-1],[0,1]];\n\n  /* Ruleset mặc định. Client có thể ghi đè (vd lấy N/walls từ CFG) bằng Core.ruleset('classic',{...}). */\n  const RULESETS={\n    classic:{id:'classic',name:'Classic',N:9,walls:10,maxPly:300}\n  };\n  const ruleset=(id,over)=>Object.assign({},RULESETS[id||'classic'],over||{});\n\n  /* Bộ đệm BFS dùng lại cho mọi lần gọi (theo từng R) để không tạo rác */\n  function make(rs){\n    const N=rs.N,WN=N-1,HALF=WN>>1;\n    const VIS=new Int32Array(N*N),DST=new Int8Array(N*N),Q=new Int16Array(N*N);let stamp=0;\n\n    const goalRow=p=>p===0?0:N-1;\n    const inb=(r,c)=>r>=0&&r<N&&c>=0&&c<N;\n    const W=(st,o,r,c)=>r>=0&&r<WN&&c>=0&&c<WN&&st.ws[o][r*WN+c]===1;\n    const setW=(st,o,r,c,v)=>{st.ws[o][r*WN+c]=v;};\n\n    /* Có tường chắn khi đi từ ô (r,c) theo hướng (dr,dc) không */\n    function blk(st,r,c,dr,dc){\n      if(dr===1)return W(st,'h',r,c)||W(st,'h',r,c-1);\n      if(dr===-1)return W(st,'h',r-1,c)||W(st,'h',r-1,c-1);\n      if(dc===1)return W(st,'v',r,c)||W(st,'v',r-1,c);\n      return W(st,'v',r,c-1)||W(st,'v',r-1,c-1);\n    }\n    /* Các ô người p có thể đi tới (gồm cả nhảy qua đối thủ, kể cả nhảy chéo khi bị tường chắn sau lưng) */\n    function moves(st,p){\n      const a=st.pl[p],o=st.pl[1-p],out=[];\n      for(const[dr,dc]of D){\n        if(blk(st,a.r,a.c,dr,dc))continue;\n        const r=a.r+dr,c=a.c+dc;if(!inb(r,c))continue;\n        if(r===o.r&&c===o.c){\n          const r2=r+dr,c2=c+dc;\n          if(inb(r2,c2)&&!blk(st,r,c,dr,dc))out.push([r2,c2]);\n          else for(const[er,ec]of D){\n            if(er*dr+ec*dc!==0||blk(st,r,c,er,ec)||!inb(r+er,c+ec))continue;\n            out.push([r+er,c+ec]);\n          }\n        }else out.push([r,c]);\n      }\n      return out;\n    }\n    /* BFS: số bước ngắn nhất từ ô s tới hàng đích của người p (99 = bị chặn kín) */\n    function dist(st,p,s){\n      const goal=goalRow(p);\n      if(s.r===goal)return 0;\n      stamp++;let h=0,t=0;const s0=s.r*N+s.c;Q[t++]=s0;VIS[s0]=stamp;DST[s0]=0;\n      while(h<t){\n        const k=Q[h++],r=(k/N)|0,c=k-r*N,d=DST[k]+1;\n        for(let i=0;i<4;i++){\n          const dr=D[i][0],dc=D[i][1];\n          if(blk(st,r,c,dr,dc))continue;\n          const r2=r+dr,c2=c+dc;\n          if(!inb(r2,c2))continue;\n          const k2=r2*N+c2;\n          if(VIS[k2]===stamp)continue;\n          if(r2===goal)return d;\n          VIS[k2]=stamp;DST[k2]=d;Q[t++]=k2;\n        }\n      }\n      return 99;\n    }\n    /* Tường không trùng/chéo với tường đã có */\n    function wallFree(st,o,r,c){\n      if(o!=='h'&&o!=='v')return false;\n      if(r<0||r>=WN||c<0||c>=WN||W(st,o,r,c))return false;\n      if(o==='h'&&(W(st,'h',r,c-1)||W(st,'h',r,c+1)||W(st,'v',r,c)))return false;\n      if(o==='v'&&(W(st,'v',r-1,c)||W(st,'v',r+1,c)||W(st,'h',r,c)))return false;\n      return true;\n    }\n    /* Đường đi mới của hai bên nếu đặt tường này; null nếu làm kín đường */\n    function wallDists(st,o,r,c){\n      setW(st,o,r,c,1);const a=dist(st,0,st.pl[0]),b=dist(st,1,st.pl[1]);setW(st,o,r,c,0);\n      return a<99&&b<99?[a,b]:null;\n    }\n    const canWall=(st,o,r,c)=>wallFree(st,o,r,c)&&wallDists(st,o,r,c)!==null;\n\n    /* ----- Vòng đời một ván ----- */\n    function newState(){\n      return{pl:[{r:N-1,c:HALF},{r:0,c:HALF}],ws:{h:new Uint8Array(WN*WN),v:new Uint8Array(WN*WN)},\n             left:[rs.walls,rs.walls],turn:0,ply:0,over:false,winner:-1,draw:false};\n    }\n    /* Kiểm tra một hành động của bên đang tới lượt. KHÔNG sửa st. */\n    function check(st,a){\n      if(!a||typeof a!=='object')return{ok:false,reason:'format'};\n      if(st.over)return{ok:false,reason:'over'};\n      const p=st.turn;\n      if(a.move){\n        const m=a.move;\n        if(!Array.isArray(m)||!Number.isInteger(m[0])||!Number.isInteger(m[1]))return{ok:false,reason:'format'};\n        return moves(st,p).some(x=>x[0]===m[0]&&x[1]===m[1])?{ok:true}:{ok:false,reason:'badmove'};\n      }\n      if(a.wall){\n        const w=a.wall;\n        if(!Number.isInteger(w.r)||!Number.isInteger(w.c))return{ok:false,reason:'format'};\n        if(st.left[p]<=0)return{ok:false,reason:'nowalls'};\n        return canWall(st,w.o,w.r,w.c)?{ok:true}:{ok:false,reason:'badwall'};\n      }\n      return{ok:false,reason:'format'};\n    }\n    /* Áp dụng hành động: kiểm tra → cập nhật → xét thắng/hòa → chuyển lượt. Sai thì không đổi gì. */\n    function apply(st,a){\n      const v=check(st,a);if(!v.ok)return v;\n      const p=st.turn;\n      if(a.move)st.pl[p]={r:a.move[0],c:a.move[1]};\n      else{setW(st,a.wall.o,a.wall.r,a.wall.c,1);st.left[p]--;}\n      st.ply++;\n      if(st.pl[p].r===goalRow(p)){st.over=true;st.winner=p;}\n      else if(rs.maxPly&&st.ply>=rs.maxPly){st.over=true;st.draw=true;}\n      else st.turn=1-p;\n      return{ok:true,over:st.over,winner:st.winner,draw:st.draw,by:p};\n    }\n\n    /* ----- Chuyển đổi để gửi qua mạng / lưu: object thuần JSON ----- */\n    function snapshot(st){\n      const walls=[];\n      for(const o of['h','v'])for(let i=0;i<WN*WN;i++)if(st.ws[o][i])walls.push({o,r:(i/WN)|0,c:i%WN});\n      return{pl:[{r:st.pl[0].r,c:st.pl[0].c},{r:st.pl[1].r,c:st.pl[1].c}],left:st.left.slice(),turn:st.turn,ply:st.ply,\n             over:st.over,winner:st.winner,draw:st.draw,walls};\n    }\n    function fromSnapshot(sn){\n      const st=newState();\n      st.pl=[{r:sn.pl[0].r,c:sn.pl[0].c},{r:sn.pl[1].r,c:sn.pl[1].c}];st.left=sn.left.slice();\n      st.turn=sn.turn;st.ply=sn.ply;st.over=!!sn.over;st.winner=sn.winner;st.draw=!!sn.draw;\n      for(const w of sn.walls)setW(st,w.o,w.r,w.c,1);\n      return st;\n    }\n\n    return{rs,N,WN,HALF,D,goalRow,inb,W,setW,blk,moves,dist,wallFree,wallDists,canWall,newState,check,apply,snapshot,fromSnapshot};\n  }\n\n  return{D,RULESETS,ruleset,make};\n})();\nif(typeof module!=='undefined')module.exports=Core;   /* để server/tools Node nạp được; trên trình duyệt đoạn này bị bỏ qua */\n\n;\n'use strict';\n/* [RULES] Lớp mỏng nối luật chơi (js/core.js) với trạng thái toàn cục S của client.\n   Giữ nguyên tên hàm cũ (goalRow, W, setW, inb, blk, moves, dist, wallFree, wallDists, canWall, D) để AI, eval, review, giao diện\n   không phải sửa gì; mọi quy tắc nằm trong core.js. Muốn đổi luật/thêm chế độ: sửa core.js hoặc thêm ruleset, KHÔNG sửa ở đây.\n   RS = ruleset đang dùng của client (hiện là Classic, cỡ bàn và số tường lấy từ CFG). */\nconst RS=Core.ruleset('classic',{N:CFG.N,walls:CFG.WALLS,maxPly:CFG.MAX_PLY});\nconst R=Core.make(RS);\nconst D=R.D;\nconst goalRow=R.goalRow;\nconst W=(o,r,c)=>R.W(S,o,r,c);\nconst setW=(o,r,c,v)=>R.setW(S,o,r,c,v);\nconst inb=R.inb;\nconst blk=(r,c,dr,dc)=>R.blk(S,r,c,dr,dc);\nconst moves=p=>R.moves(S,p);\nconst dist=(p,s)=>R.dist(S,p,s);\nconst wallFree=(o,r,c)=>R.wallFree(S,o,r,c);\nconst wallDists=(o,r,c)=>R.wallDists(S,o,r,c);\nconst canWall=(o,r,c)=>R.canWall(S,o,r,c);\n\n;\n'use strict';\n/* [AI/REGISTRY] Danh sách các mô hình AI. Mỗi AI là một object:\n     { id:'duy-nhat', name:'Tên hiển thị', desc:'Mô tả ngắn', decide(p){...} }\n   decide(p) nhận chỉ số bên p (0 = Trắng, 1 = Đen), đọc trạng thái S + hàm trong rules.js,\n   rồi trả về {move:[r,c]} hoặc {wall:{o,r,c}}. Không được sửa S trực tiếp.\n   Thêm AI mới: tạo file js/ai/<ten>.js gọi AIs.register({...}), rồi thêm <script> vào index.html\n   (sau registry.js). Menu tự liệt kê mọi AI đã đăng ký. */\nconst AIs={\n  list:[],\n  register(def){this.list.push(def);},\n  get(id){return this.list.find(a=>a.id===id)||this.list[0];},\n  defaultId(){return this.list[0].id;}\n};\n\n;\n'use strict';\n/* [AI/TOOLS] Đồ nghề dùng chung cho các AI \"có tính cách\" (attacker, defender, và AI sau này).\n   Chỉ đọc S + rules.js, không sửa S (đặt tường thử xong luôn gỡ ra). Không đụng 3D/DOM.\n   Quy ước: p = bên đang suy nghĩ, op = 1-p. \"net\" của tường = (đối thủ chậm thêm) - (mình chậm thêm). */\nconst AITools=(function(){\n  const PAR=new Int16Array(N*N),SEEN=new Int32Array(N*N),QQ=new Int16Array(N*N);let st=0;\n\n  /* ----- ngẫu nhiên ----- */\n  const chance=p=>Math.random()<p;\n  const between=r=>rand(r[0],r[1]);                         /* số thực trong [a,b] */\n  const intBetween=r=>Math.floor(rand(r[0],r[1]+1));        /* số nguyên trong [a,b] */\n  function weighted(pairs){                                 /* [[giá trị, trọng số],...] → một giá trị */\n    let t=0;for(const x of pairs)t+=x[1];\n    let r=Math.random()*t;\n    for(const x of pairs){r-=x[1];if(r<=0)return x[0];}\n    return pairs[pairs.length-1][0];\n  }\n  /* Softmax: điểm cao được ưu tiên, nhiệt độ thấp ≈ luôn chọn điểm cao nhất, cao ≈ gần như ngẫu nhiên */\n  function softPick(items,score,temp){\n    if(items.length<2)return items[0];\n    const ss=items.map(score),mx=Math.max(...ss),ws=ss.map(s=>Math.exp((s-mx)/temp));\n    let r=Math.random()*ws.reduce((a,b)=>a+b,0);\n    for(let i=0;i<items.length;i++){r-=ws[i];if(r<=0)return items[i];}\n    return items[items.length-1];\n  }\n\n  /* ----- đường đi ----- */\n  /* Một đường ngắn nhất của q tới đích (mảng ô); null nếu bị chặn kín */\n  function path(q){\n    const goal=goalRow(q),s=S.pl[q],s0=s.r*N+s.c;\n    if(s.r===goal)return[s0];\n    st++;let h=0,t=0;QQ[t++]=s0;SEEN[s0]=st;PAR[s0]=-1;\n    while(h<t){\n      const k=QQ[h++],r=(k/N)|0,c=k-r*N;\n      for(let i=0;i<4;i++){\n        const dr=D[i][0],dc=D[i][1];\n        if(blk(r,c,dr,dc))continue;\n        const r2=r+dr,c2=c+dc;if(!inb(r2,c2))continue;\n        const k2=r2*N+c2;if(SEEN[k2]===st)continue;\n        SEEN[k2]=st;PAR[k2]=k;QQ[t++]=k2;\n        if(r2===goal){const out=[];for(let x=k2;x!==-1;x=PAR[x])out.push(x);return out.reverse();}\n      }\n    }\n    return null;\n  }\n  /* Các tường có thể cắt đường ngắn nhất của q (mỗi bước trên đường có đúng 2 tường chặn được) */\n  function cutWalls(q){\n    const pa=path(q);if(!pa||pa.length<2)return[];\n    const seen=new Set(),out=[];\n    for(let i=0;i+1<pa.length;i++){\n      const a=pa[i],b=pa[i+1],r=(a/N)|0,c=a-r*N,r2=(b/N)|0,c2=b-r2*N;\n      const cand=r===r2?[['v',r,Math.min(c,c2)],['v',r-1,Math.min(c,c2)]]:[['h',Math.min(r,r2),c],['h',Math.min(r,r2),c-1]];\n      for(const[o,wr,wc]of cand){\n        const key=o+wr+','+wc;if(seen.has(key)||!wallFree(o,wr,wc))continue;\n        seen.add(key);out.push({o,r:wr,c:wc});\n      }\n    }\n    return out;\n  }\n\n  /* ----- hình học tường: các điểm nút (góc giữa 4 ô) mà tường chạm vào ----- */\n  const ends=(o,r,c)=>o==='h'?[[r,c-1],[r,c+1]]:[[r-1,c],[r+1,c]];          /* hai đầu mút của tường (theo tọa độ nút) */\n  const pts=(o,r,c)=>[...ends(o,r,c),[r,c]];                                  /* đầu mút + tâm */\n  const eq=(x,y)=>x[0]===y[0]&&x[1]===y[1];\n  /* Nút (er,ec) đã có tường đi qua / kết thúc ở đó, hoặc nằm ngoài rìa bàn */\n  const anchored=(er,ec)=>er<0||er>=WN||ec<0||ec>=WN||\n    W('v',er,ec)||W('v',er-1,ec)||W('v',er+1,ec)||W('h',er,ec)||W('h',er,ec-1)||W('h',er,ec+1);\n  /* Số đầu mút (0..2) của tường mới nối liền với tường khác hoặc mép bàn: tường nối nhau tạo hàng rào dài, khó vòng qua */\n  const links=(o,r,c)=>ends(o,r,c).reduce((n,e)=>n+(anchored(e[0],e[1])?1:0),0);\n  /* Hai tường chạm nhau (đầu mút của tường này nằm trên tường kia) */\n  function connected(a,b){\n    const pa=pts(a.o,a.r,a.c),pb=pts(b.o,b.r,b.c);\n    for(const x of ends(a.o,a.r,a.c))for(const y of pb)if(eq(x,y))return true;\n    for(const x of ends(b.o,b.r,b.c))for(const y of pa)if(eq(x,y))return true;\n    return false;\n  }\n\n  /* ----- đánh giá tường ----- */\n  /* Mọi tường hợp lệ của p, kèm: opGain (đối thủ chậm thêm), myLoss (mình chậm thêm), links */\n  function walls(p){\n    const op=1-p,myD=dist(p,S.pl[p]),opD=dist(op,S.pl[op]),out=[];\n    for(const o of['h','v'])for(let r=0;r<WN;r++)for(let c=0;c<WN;c++){\n      if(!wallFree(o,r,c))continue;\n      const nd=wallDists(o,r,c);if(!nd)continue;\n      out.push({o,r,c,opGain:nd[op]-opD,myLoss:nd[p]-myD,links:links(o,r,c)});\n    }\n    return out;\n  }\n  /* \"Độ dễ tổn thương\" của q: tường tốt nhất mà ĐỐI THỦ của q còn đặt được sẽ có net bao nhiêu (0 nếu đối thủ hết tường) */\n  function harm(q){\n    const o=1-q;if(S.left[o]<=0)return 0;\n    const dq=dist(q,S.pl[q]),dop=dist(o,S.pl[o]);let best=0;\n    for(const w of cutWalls(q)){\n      const nd=wallDists(w.o,w.r,w.c);if(!nd)continue;\n      const net=(nd[q]-dq)-(nd[o]-dop);if(net>best)best=net;\n    }\n    return best;\n  }\n\n  /* ----- tình huống bắt buộc ----- */\n  const winNow=p=>{const g=goalRow(p),m=moves(p).find(x=>x[0]===g);return m?{move:m}:null;};\n  /* Đối thủ về đích được ngay nước sau: tìm tường chặn được (ưu tiên làm đối thủ xa nhất, mình ít chậm nhất). null nếu không cần/không chặn được. */\n  function block(p){\n    if(S.left[p]<=0)return null;\n    const op=1-p,g=goalRow(op);\n    if(!moves(op).some(m=>m[0]===g))return null;\n    let best=null,bs=-1e9;\n    for(const o of['h','v'])for(let r=0;r<WN;r++)for(let c=0;c<WN;c++){\n      if(!wallFree(o,r,c))continue;\n      setW(o,r,c,1);\n      if(!moves(op).some(m=>m[0]===g)){\n        const a=dist(0,S.pl[0]),b=dist(1,S.pl[1]);\n        if(a<99&&b<99){const sc=(op===0?a:b)*2-(p===0?a:b)*3;if(sc>bs){bs=sc;best={wall:{o,r,c}};}}\n      }\n      setW(o,r,c,0);\n    }\n    return best;\n  }\n  /* Các nước đi quân kèm đường còn lại sau nước đó */\n  const steps=p=>moves(p).map(m=>({m,d:dist(p,{r:m[0],c:m[1]})}));\n\n  return{chance,between,intBetween,weighted,softPick,path,cutWalls,ends,links,connected,walls,harm,winNow,block,steps};\n})();\n\n;\n'use strict';\n/* [AI/BIET] \"Mr. Biết\" — boss: tìm kiếm sâu + đọc đối thủ + chọn nước mềm để khó đoán.\n   ----------------------------------------------------------------\n   Không có \"chế độ\" cứng. Tấn công hay phòng thủ đều do một cây tìm kiếm quyết định, nên tự thích nghi mọi chiến thuật:\n   1. TÌM KIẾM  negamax alpha-beta + đào sâu dần + bảng băm (Zobrist). Mỗi nút thử các nước đi quân và những tường cắt\n      đường ngắn nhất của đối thủ (xếp theo lợi). Có kéo dài khi đối thủ sắp về đích. Giới hạn bằng số nút và thời gian.\n   2. CHẤM LÁ   (đường đối thủ - đường mình) + giá trị tường dư hai bên. Tường dư là \"đạn\": mình còn nhiều thì dám dẫn\n      sát, đối thủ còn nhiều thì không dám chủ quan. Giá trị này chính là cần gạt công/thủ.\n   3. ĐỌC ĐỐI THỦ  đo xem mỗi tường đối thủ đã đặt làm mình chậm thêm bao nhiêu bước (trung bình trượt). Đối thủ đặt tường\n      dở thì tường dư của họ bị coi rẻ (mình dám chạy), đặt tường hiểm thì coi đắt (mình giữ tường, đi cẩn thận).\n   4. KHÓ ĐOÁN  mỗi ván lệch nhẹ giá trị tường; ở gốc chọn mềm (softmax) giữa các nước chỉ kém nước tốt nhất < margin bước,\n      lúc mở màn margin rộng hơn. Có đường thắng chắc thì bỏ ngẫu nhiên, đi nước thắng nhanh nhất.\n   5. CHỐNG BÍ   thế cờ đã lặp lại thì bị phạt (rep) nên không đi qua đi lại, tự phá thế hòa.\n   Kết quả đấu thử (tools/tournament.js, cả hai phe): thắng 95-100% mọi AI trong js/ai/, ~92% một bot ngoài dùng Eval.score.\n   Luôn đúng: về đích được thì về. Chỉnh: CFG.AI.biet trong config.js (thử nhanh: node tools/tournament.js biet attacker --set AI.biet.nodes=8000). */\n(function(){\n  const T=AITools,WIN=1000,INF=1e9,NN=N*N,mem=[null,null];\n\n  /* ----- bảng băm Zobrist (hai số 32 bit) ----- */\n  let sd=0x2545F491;\n  const rnd32=()=>{sd^=sd<<13;sd^=sd>>>17;sd^=sd<<5;return sd|0;};\n  const mk=n=>{const a=new Int32Array(n),b=new Int32Array(n);for(let i=0;i<n;i++){a[i]=rnd32();b[i]=rnd32();}return[a,b];};\n  const WW=WN*WN,L1=CFG.WALLS+1;\n  const[ZPa,ZPb]=mk(2*NN),[ZWa,ZWb]=mk(2*WW),[ZLa,ZLb]=mk(2*L1),[ZTa,ZTb]=mk(2);\n  let ha=0,hb=0;\n  const TTN=1<<17,TTM=TTN-1,ttK=new Int32Array(TTN),ttV=new Float32Array(TTN),ttD=new Int8Array(TTN),ttF=new Int8Array(TTN),ttM=new Int16Array(TTN);\n  const flip=()=>{ha^=ZTa[0]^ZTa[1];hb^=ZTb[0]^ZTb[1];};\n  function hashAll(p){\n    ha=hb=0;\n    for(let q=0;q<2;q++){const s=S.pl[q],i=q*NN+s.r*N+s.c,l=q*L1+S.left[q];ha^=ZPa[i]^ZLa[l];hb^=ZPb[i]^ZLb[l];}\n    for(let k=0;k<WW;k++){if(S.ws.h[k]){ha^=ZWa[k];hb^=ZWb[k];}if(S.ws.v[k]){ha^=ZWa[WW+k];hb^=ZWb[WW+k];}}\n    ha^=ZTa[p];hb^=ZTb[p];\n  }\n\n  /* ----- bàn cờ dạng mảng phẳng cho BFS nhanh: E[ô*4+hướng]=1 nếu bị tường chặn. Hướng: 0 lên, 1 xuống, 2 trái, 3 phải ----- */\n  const E=new Uint8Array(NN*4),NB=new Int16Array(NN*4).fill(-1);\n  for(let r=0;r<N;r++)for(let c=0;c<N;c++){const k=r*N+c;if(r>0)NB[k*4]=k-N;if(r<N-1)NB[k*4+1]=k+N;if(c>0)NB[k*4+2]=k-1;if(c<N-1)NB[k*4+3]=k+1;}\n  function edges(o,r,c,v){\n    const a=r*N+c;\n    if(o==='h'){E[a*4+1]=E[(a+1)*4+1]=E[(a+N)*4]=E[(a+N+1)*4]=v;}          /* tường ngang chặn đi xuống từ 2 ô trên, đi lên từ 2 ô dưới */\n    else{E[a*4+3]=E[(a+N)*4+3]=E[(a+1)*4+2]=E[(a+N+1)*4+2]=v;}              /* tường dọc chặn đi phải từ 2 ô trái, đi trái từ 2 ô phải */\n  }\n  function syncEdges(){E.fill(0);for(let r=0;r<WN;r++)for(let c=0;c<WN;c++){if(W('h',r,c))edges('h',r,c,1);if(W('v',r,c))edges('v',r,c,1);}}\n  /* Bản đồ \"còn bao nhiêu bước tới đích\" cho người q: BFS ngược từ cả hàng đích (99 = không tới được) */\n  const F=[new Int8Array(NN),new Int8Array(NN)],BQ=new Int16Array(NN);\n  const FS=new Int8Array(NN);   /* bản đồ tạm để chấm tường thử, không đè lên F */\n  function field(q,tmp){\n    const f=tmp||F[q];f.fill(99);let h=0,t=0;const g=q===0?0:N-1;\n    for(let c=0;c<N;c++){const k=g*N+c;f[k]=0;BQ[t++]=k;}\n    while(h<t){const k=BQ[h++],d=f[k]+1;\n      for(let i=0;i<4;i++){const n=NB[k*4+i];if(n>=0&&!E[k*4+i]&&f[n]===99){f[n]=d;BQ[t++]=n;}}}\n    return f;\n  }\n  const pos=q=>S.pl[q].r*N+S.pl[q].c;\n\n  /* ----- trạng thái tìm kiếm (module-level để khỏi cấp phát) ----- */\n  let nodes=0,maxNodes=0,deadline=0,aborted=false,rootDepth=0,TOPR=12,TOP=6,TOP2=4,TEMPO=.5;\n  const BIG=3*WIN,MAXM=40;\n  const VT=[new Float64Array(L1),new Float64Array(L1)];   /* VT[bên][w] = giá trị w tường dư (bước đi), lõm: tường thứ k đáng A*R^(k-1) */\n  const leaf=(p,dm,dop)=>(dop-dm)+VT[p][S.left[p]]-VT[1-p][S.left[1-p]]+TEMPO;\n  function setVal(side,a,R){let t=0,m=a;for(let w=0;w<=CFG.WALLS;w++){VT[side][w]=t;t+=m;m*=R;}}\n  const KB=[],SB=[];for(let i=0;i<40;i++){KB.push(new Int16Array(MAXM));SB.push(new Float32Array(MAXM));}   /* bộ đệm nước đi theo tầng */\n\n  /* Mã nước đi: đi quân = r*N+c (0..80); tường = 100 + (h?0:64) + r*8 + c */\n  const wcode=(o,r,c)=>100+(o==='h'?0:WW)+r*WN+c;\n  const wdec=k=>{k-=100;const o=k<WW?'h':'v';if(o==='v')k-=WW;return{o,r:(k/WN)|0,c:k%WN};};\n\n  /* Làm / hoàn tác một nước (sửa S và E tại chỗ, luôn hoàn tác trước khi thoát) */\n  function make(p,code){\n    if(code<100){\n      const s=S.pl[p],old=s.r*N+s.c;\n      ha^=ZPa[p*NN+old]^ZPa[p*NN+code];hb^=ZPb[p*NN+old]^ZPb[p*NN+code];\n      s.r=(code/N)|0;s.c=code%N;return old;\n    }\n    const w=wdec(code),i=(w.o==='h'?0:WW)+w.r*WN+w.c,l=p*L1+S.left[p];\n    setW(w.o,w.r,w.c,1);edges(w.o,w.r,w.c,1);S.left[p]--;\n    ha^=ZWa[i]^ZLa[l]^ZLa[l-1];hb^=ZWb[i]^ZLb[l]^ZLb[l-1];return 0;\n  }\n  function unmake(p,code,old){\n    if(code<100){\n      const s=S.pl[p],cur=s.r*N+s.c;\n      ha^=ZPa[p*NN+cur]^ZPa[p*NN+old];hb^=ZPb[p*NN+cur]^ZPb[p*NN+old];\n      s.r=(old/N)|0;s.c=old%N;return;\n    }\n    const w=wdec(code),i=(w.o==='h'?0:WW)+w.r*WN+w.c,l=p*L1+S.left[p];\n    setW(w.o,w.r,w.c,0);edges(w.o,w.r,w.c,0);S.left[p]++;\n    ha^=ZWa[i]^ZLa[l]^ZLa[l+1];hb^=ZWb[i]^ZLb[l]^ZLb[l+1];\n  }\n\n  /* Nước đi quân của p vào mảng k (kể cả nhảy qua đối thủ), trả về số nước. Cùng luật với rules.moves. */\n  function pawnMoves(p,k){\n    const a=pos(p),o=pos(1-p);let n=0;\n    for(let d=0;d<4;d++){\n      if(E[a*4+d])continue;const b=NB[a*4+d];if(b<0)continue;\n      if(b!==o){k[n++]=b;continue;}\n      const b2=NB[b*4+d];\n      if(b2>=0&&!E[b*4+d])k[n++]=b2;\n      else for(let e=0;e<4;e++){if(((e^d)>>1)===0)continue;const x=NB[b*4+e];if(x>=0&&!E[b*4+e])k[n++]=x;}   /* hướng vuông góc: 0,1 là dọc, 2,3 là ngang */\n    }\n    return n;\n  }\n\n  /* Các nước của p ở tầng ply, xếp theo độ hứa hẹn: đi quân (tiến lên tốt nhất) + tường cắt đường ngắn nhất của đối thủ\n     (lợi lớn nhất). Ghi vào KB/SB[ply], trả về số nước. fm/fo = bản đồ bước của mình/đối thủ (đã tính sẵn). */\n  function gen(p,ply,topK,ttMove,fm,fo){\n    const op=1-p,kb=KB[ply],sb=SB[ply],a=pos(p),pa=pos(op);let n=pawnMoves(p,kb);\n    const d0=fm[a];\n    for(let i=0;i<n;i++){const k=kb[i];sb[i]=(d0-fm[k])*1.2+(((k/N)|0)===goalRow(p)?50:0);}\n    if(S.left[p]>0&&fo[pa]>0&&fo[pa]<99){\n      const e0=fo[pa],tk=[],ts=[];let x=pa;\n      while(fo[x]>0){                                    /* đi theo một đường ngắn nhất của đối thủ, mỗi bước thử 2 tường cắt được */\n        let y=-1,dir=0;\n        for(let d=0;d<4;d++){const z=NB[x*4+d];if(z>=0&&!E[x*4+d]&&fo[z]===fo[x]-1){y=z;dir=d;break;}}\n        const r=(x/N)|0,c=x%N;\n        const c1=dir<2?[wcode('h',dir===1?r:r-1,c),wcode('h',dir===1?r:r-1,c-1)]:[wcode('v',r,dir===3?c:c-1),wcode('v',r-1,dir===3?c:c-1)];\n        for(const key of c1){\n          if(tk.indexOf(key)>=0)continue;const w=wdec(key);if(!wallFree(w.o,w.r,w.c))continue;\n          edges(w.o,w.r,w.c,1);const g=field(op,FS)[pa]-e0;edges(w.o,w.r,w.c,0);\n          if(g>0&&g<50){tk.push(key);ts.push(g*1.3-.4+T.links(w.o,w.r,w.c)*.15);}\n        }\n        x=y;\n      }\n      const idx=ts.map((_,i)=>i).sort((u,v)=>ts[v]-ts[u]);\n      for(let i=0;i<idx.length&&i<topK&&n<MAXM;i++){kb[n]=tk[idx[i]];sb[n]=ts[idx[i]];n++;}\n    }\n    if(ttMove>=0)for(let i=0;i<n;i++)if(kb[i]===ttMove)sb[i]+=100;\n    for(let i=1;i<n;i++){const k=kb[i],v=sb[i];let j=i-1;while(j>=0&&sb[j]<v){kb[j+1]=kb[j];sb[j+1]=sb[j];j--;}kb[j+1]=k;sb[j+1]=v;}\n    return n;\n  }\n\n  /* Negamax alpha-beta. Điểm theo góc nhìn người đi p. Trả BIG nếu thế cờ phạm luật (một bên bị nhốt kín). */\n  function nm(d,p,alpha,beta,ply){\n    if(aborted)return 0;\n    if((++nodes&127)===0&&(nodes>maxNodes||Date.now()>deadline)){aborted=true;return 0;}\n    const op=1-p,fm=field(p),fo=field(op),dm=fm[pos(p)],dop=fo[pos(op)];\n    if(dm>=99||dop>=99)return BIG;\n    const mvb=KB[ply];\n    {const n=pawnMoves(p,mvb),g=goalRow(p);for(let i=0;i<n;i++)if(((mvb[i]/N)|0)===g)return WIN-ply;}\n    if(d<=0){\n      /* kéo dài: đối thủ sắp về đích mà mình còn tường thì phải nhìn tiếp xem có chặn nổi không */\n      if(dop<=1&&S.left[p]>0&&ply<rootDepth+3)d=1;else return leaf(p,dm,dop);\n    }\n    const i0=ha&TTM;let ttMove=-1;\n    if(ttK[i0]===hb){\n      ttMove=ttM[i0];\n      if(ttD[i0]>=d){\n        const v=ttV[i0],f=ttF[i0];\n        if(f===0||(f===1&&v>=beta)||(f===2&&v<=alpha))return v;\n      }\n    }\n    const n=gen(p,ply,d>=3?TOP:TOP2,ttMove,fm,fo),kb=KB[ply],a0=alpha;\n    let best=-INF,bm=-1;\n    for(let i=0;i<n;i++){\n      const k=kb[i],old=make(p,k);flip();\n      const v=-nm(d-1,op,-beta,-alpha,ply+1);\n      flip();unmake(p,k,old);\n      if(aborted)return 0;\n      if(v<=-BIG/2)continue;                                  /* nước phạm luật */\n      if(v>best){best=v;bm=k;}\n      if(v>alpha)alpha=v;\n      if(alpha>=beta)break;\n    }\n    if(best===-INF)return leaf(p,dm,dop);\n    ttK[i0]=hb;ttV[i0]=best;ttD[i0]=d;ttM[i0]=bm;ttF[i0]=best<=a0?2:best>=beta?1:0;\n    return best;\n  }\n\n  /* Tìm ở gốc tới độ sâu d. Các nước điểm trong khoảng margin của nước tốt nhất được chấm chính xác (để chọn mềm). */\n  function rootSearch(p,d,roots,margin,seen,rep){\n    const op=1-p,res=[];let best=-INF;\n    for(const k of roots){\n      const old=make(p,k);flip();\n      const key=ha+':'+hb,lo=best-margin;\n      let v=-nm(d-1,op,-INF,-lo,1);\n      flip();unmake(p,k,old);\n      if(aborted)return null;\n      if(v<=-BIG/2)continue;\n      if(Math.abs(v)<WIN/2)v-=rep*(seen.get(key)||0);      /* lặp lại thế cờ đã qua thì bị phạt: tránh đi qua đi lại, ép phá thế bí */\n      res.push({k,v:v<=lo?-INF:v,hi:v});\n      if(v>best)best=v;\n    }\n    res.sort((x,y)=>y.hi-x.hi);\n    return{res,best};\n  }\n\n  /* ----- đọc đối thủ ----- */\n  function observe(p,M){\n    const op=1-p;\n    if(S.left[op]<M.opLeft&&M.myDist>=0){                       /* đối thủ vừa đặt một tường: nó làm mình chậm bao nhiêu? */\n      const g=dist(p,S.pl[p])-M.myDist;\n      M.sumEff+=clamp(g,0,6);M.nEff++;\n    }\n  }\n  const effOp=M=>(M.prior*M.K+M.sumEff)/(M.K+M.nEff);\n\n  function fresh(){\n    const C=CFG.AI.biet,j=C.jitter;\n    return{a:C.wallA*rand(1-j,1+j),tempo:C.tempo+rand(-.1,.1),prior:C.effPrior,K:C.effK,sumEff:0,nEff:0,opLeft:CFG.WALLS,myDist:-1,seen:new Map()};\n  }\n\n  AIs.register({\n    id:'biet',\n    worker:true,                             /* App chạy AI này ở Web Worker (js/ai/worker.js) để không làm đứng trang; lỗi worker thì tự gọi decide() ở luồng chính */\n    name:'Mr. Biết',\n    dbg:{pawnMoves,field,syncEdges,pos,F},   /* chỉ để tools/ kiểm thử đối chiếu với rules.js */\n    desc:'Boss: tìm kiếm sâu, đọc lối chơi đối thủ để khai thác, công thủ tùy thế cờ, mỗi nước đi đều khó đoán',\n\n    decide(p){\n      const C=CFG.AI.biet,op=1-p;\n      if(!mem[p]||S.ply<2)mem[p]=fresh();\n      const M=mem[p];observe(p,M);\n      const win=T.winNow(p);if(win){win.why='win';return win;}\n\n      /* thông số của lần suy nghĩ này */\n      TEMPO=M.tempo;setVal(p,M.a,C.wallR);\n      setVal(op,M.a*clamp(effOp(M)/C.effPrior,C.effLo,C.effHi),C.wallR);\n      TOPR=C.topRoot;TOP=C.top;TOP2=C.top2;\n      syncEdges();ttK.fill(0);hashAll(p);\n      nodes=0;maxNodes=C.nodes;aborted=false;\n      /* Trên luồng chính của trình duyệt (worker không dùng được) thì nghĩ ngắn hơn để đỡ giật; ở worker/Node dùng đủ C.ms */\n      deadline=Date.now()+(typeof window!=='undefined'&&C.msMain?C.msMain:C.ms);\n\n      const margin=C.margin*(S.ply<C.openPly?C.openBoost:1);\n      const fm=field(p),fo=field(op),rn=gen(p,0,TOPR,-1,fm,fo),roots=Array.from(KB[0].subarray(0,rn));\n      let last=null;\n      const sv={pl:S.pl.map(x=>({r:x.r,c:x.c})),left:S.left.slice(),h:S.ws.h.slice(),v:S.ws.v.slice()};\n      try{\n        for(let d=1;d<=C.depth;d++){\n          rootDepth=d;\n          const r=rootSearch(p,d,last?last.res.map(x=>x.k):roots,margin,M.seen,C.rep);\n          if(!r)break;\n          last=r;\n          if(Math.abs(r.best)>WIN/2)break;        /* đã thấy thắng/thua chắc */\n        }\n      }catch(e){last=null;}                       /* lỗi bất ngờ: bỏ kết quả, đi nước ngắn nhất */\n      finally{                                    /* luôn trả thế cờ về như cũ dù tìm kiếm bị ngắt giữa chừng */\n        for(let i=0;i<2;i++){S.pl[i].r=sv.pl[i].r;S.pl[i].c=sv.pl[i].c;S.left[i]=sv.left[i];}\n        S.ws.h.set(sv.h);S.ws.v.set(sv.v);syncEdges();hashAll(p);\n      }\n      let act,why='search';\n      if(!last){const m=T.steps(p).sort((x,y)=>x.d-y.d)[0].m;act={move:m};why='fallback';}\n      else{\n        const sure=Math.abs(last.best)>WIN/2,cand=last.res.filter(x=>x.v>-INF&&x.v>=last.best-(sure?0:margin));\n        const pick=sure?cand[0]:T.softPick(cand,x=>x.v,C.temp);\n        act=pick.k<100?{move:[(pick.k/N)|0,pick.k%N]}:{wall:wdec(pick.k)};\n        if(sure)why=last.best>0?'win':'lost';\n      }\n      act.why=why;\n\n      /* ghi nhớ để lần sau đo hiệu quả tường của đối thủ */\n      const s=S.pl[p];let md;\n      if(act.wall){setW(act.wall.o,act.wall.r,act.wall.c,1);md=dist(p,s);setW(act.wall.o,act.wall.r,act.wall.c,0);}\n      else{const r0=s.r,c0=s.c;s.r=act.move[0];s.c=act.move[1];md=dist(p,s);s.r=r0;s.c=c0;}\n      M.myDist=md;M.opLeft=S.left[op];\n      const k2=make(p,act.wall?wcode(act.wall.o,act.wall.r,act.wall.c):act.move[0]*N+act.move[1]);flip();   /* ghi thế cờ sau nước vừa chọn */\n      const key=ha+':'+hb;M.seen.set(key,(M.seen.get(key)||0)+1);flip();unmake(p,act.wall?wcode(act.wall.o,act.wall.r,act.wall.c):act.move[0]*N+act.move[1],k2);\n      return act;\n    }\n  });\n})();\n\n;\n'use strict';\n/* [AI/WORKER] Chạy các AI nặng (hiện chỉ Mr. Biết) ở luồng nền để trang không bị đứng hình khi nó suy nghĩ.\n   Worker nạp đúng các file logic thuần (không đụng DOM/3D) và giữ một bản S riêng; mỗi yêu cầu gửi kèm thế cờ,\n   worker chép vào S rồi gọi decide() y như trên luồng chính. Bộ nhớ của AI (đọc đối thủ, thế cờ đã lặp) nằm lại trong worker\n   suốt ván, vẫn tự đặt lại khi S.ply < 2 (ván mới).\n   Giao thức: nhận {id,ai,p,ply,pl,left,h,v} → trả {id,act}  (act = null nếu lỗi → bên gọi tự tính lại trên luồng chính). */\n\nself.onmessage=function(e){\n  const m=e.data;\n  let act=null;\n  try{\n    S.pl=m.pl;S.left=m.left;S.ws={h:m.h,v:m.v};S.ply=m.ply;S.turn=m.p;S.over=false;\n    act=AIs.get(m.ai).decide(m.p);\n  }catch(err){act=null;}\n  self.postMessage({id:m.id,act:act});\n};\n";
